const lead = $input.first().json;
const required = ['name', 'company', 'budget', 'companySize', 'problem', 'timeline'];
const missing = required.filter((field) => lead[field] === undefined || lead[field] === null || String(lead[field]).trim() === '');
if (missing.length) {
  return [{ json: { ...lead, qualificationScore: 0, classification: 'Needs Review', reasons: ['Missing required fields: ' + missing.join(', ')], explanation: 'Lead cannot be scored until required fields are provided.' } }];
}
let score = 0;
const reasons = [];
if (Number(lead.budget) >= 5000) { score += 30; reasons.push('Budget meets the target threshold'); }
if (String(lead.timeline).toLowerCase().includes('month')) { score += 25; reasons.push('Buying timeline is within one month'); }
if (String(lead.problem).trim().length >= 20) { score += 25; reasons.push('The business problem is clearly described'); }
if (Number(lead.companySize) >= 10) { score += 20; reasons.push('Company size suggests a meaningful use case'); }
const classification = score >= 75 ? 'Hot Lead' : score >= 50 ? 'Warm Lead' : score > 0 ? 'Cold Lead' : 'Needs Review';
return [{ json: { ...lead, qualificationScore: score, classification, reasons, explanation: classification + ': scored ' + score + '/100 based on budget, timeline, problem clarity, and company size.' } }];

